package com.autoops.machine.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="machines") public class Machine { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(nullable=false) private String hostname; @Column(name="ssh_port",nullable=false) private Integer sshPort=22; @Column(name="operating_system") private String operatingSystem; @Column(name="os_version") private String osVersion; @Column(name="created_by",nullable=false) private Long createdBy; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); @Column(name="deleted_at") private Instant deletedAt; public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getHostname(){return hostname;} public void setHostname(String v){hostname=v;} public Integer getSshPort(){return sshPort;} public void setSshPort(Integer v){sshPort=v;} public String getOperatingSystem(){return operatingSystem;} public void setOperatingSystem(String v){operatingSystem=v;} public String getOsVersion(){return osVersion;} public void setOsVersion(String v){osVersion=v;} public Long getCreatedBy(){return createdBy;} public void setCreatedBy(Long v){createdBy=v;} }
